                    dtypes |= {o.dtype.name}
                else:
                    # check for single value
                    dtypes |= {type(o).__name__}

            # allowed are a superset
            if not len(dtypes) or _ALLOWED_DTYPES[dtype_check].issuperset(dtypes):
                return True

    return False
