                        dtypes.update(s.astype(str).unique())
                    else:
                        dtypes.add(str(s))
                elif isinstance(o, np.ndarray):
                    dtypes.add(o.dtype.name)
            if len(dtypes) > 0 and _ALLOWED_DTYPES[dtype_check].issuperset(dtypes):
                return True
